// Conforms to ../backend/contract.json for /orders:
//   request:  { page } — integer starting at 1
//   response: { items: array of { id }, next_page: integer or null }
// Exported API is unchanged: fetchAll(fetchPage) -> flat array of items.
export async function fetchAll(fetchPage) {
  const items = [];
  let page = 1;
  do {
    const data = await fetchPage({ page });
    items.push(...(data.items ?? []));
    page = data.next_page; // null terminates pagination (contract)
  } while (page != null); // != also treats a missing next_page as terminal
  return items;
}
